<script setup lang="ts">import {ref} from "vue";import {CalendarClock,AlertTriangle} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";setPageMeta("Smart Agenda","Calendar conflicts, overdue work and suggested meeting times.");const mode=ref('Week'),days=[{day:'Mon 21',events:[['09:00','Finance close review','confirmed'],['14:00','Descon proposal','confirmed']]},{day:'Tue 22',events:[['10:30','Leadership sync','confirmed'],['11:00','Payroll approval','conflict']]},{day:'Wed 23',events:[['09:30','CRM pipeline review','confirmed']]},{day:'Thu 24',events:[['15:00','Supplier onboarding','suggested']]},{day:'Fri 25',events:[['11:00','Product demo','confirmed']]}];</script><template><AppShell><PageHeader title="Smart Agenda" description="AI suggestions require your approval before calendar or task changes"><template #actions><select v-model="mode" class="field w-32"><option>Week</option><option>Agenda</option></select></template></PageHeader><div class="grid gap-4 xl:grid-cols-[1fr_20rem]"><Panel title="21–25 September 2026"><div class="grid min-w-[760px] grid-cols-5 divide-x divide-line overflow-x-auto"><section v-for="d in days" :key="d.day" class="min-h-96 p-3"><p class="label-caps">{{d.day}}</p><div class="mt-3 space-y-2"><div v-for="e in d.events" :key="e[0]" class="rounded-md border border-line p-2" :class="e[2]==='conflict'?'bg-danger-subtle':e[2]==='suggested'?'bg-warning-subtle':'bg-surface'"><p class="num text-2xs text-content-muted">{{e[0]}}</p><p class="mt-1 text-xs font-medium text-content">{{e[1]}}</p><StatusBadge v-if="e[2]!=='confirmed'" class="mt-2" :status="e[2]"/></div></div></section></div></Panel><div class="space-y-4"><Panel title="Attention"><div class="space-y-3 p-4"><div class="flex gap-2"><AlertTriangle class="mt-0.5 size-4 text-danger"/><div><p class="text-xs font-medium text-content">Tuesday conflict</p><p class="text-2xs text-content-muted">Leadership sync overlaps payroll approval by 30 minutes.</p></div></div><div class="flex gap-2"><CalendarClock class="mt-0.5 size-4 text-warning"/><div><p class="text-xs font-medium text-content">Suggested time</p><p class="text-2xs text-content-muted">Move payroll approval to 12:00 with all attendees available.</p></div></div><ZButton @click="showToast('Change approved','Calendar update is preview-only until an integration is connected.','info')">Approve suggestion</ZButton></div></Panel><Panel title="Overdue tasks"><ul class="divide-y divide-line text-xs"><li class="p-3">Review vendor agreement · 2 days</li><li class="p-3">Approve campaign copy · 1 day</li></ul></Panel></div></div></AppShell></template>